UPDATE T_BLDCON_MST
   SET ACC_TOKEN  = #{accessToken}
      ,REF_TOKEN  = #{refresh_token}
      ,EXPRE_TIME = #{expires_in}
      ,TOKEN_YN   = 'Y'
      ,MOD_DTM    = NOW()
 WHERE USER_UUID = #{userUuid}
